  add("linearalg", "la5", 0, [{"type":"regular","q":"Find the characteristic polynomial of \\(\\begin{pmatrix}4&1\\\\0&2\\end{pmatrix}\\).","answer":"\\((4-\\lambda)(2-\\lambda)\\) or \\(\\lambda^2 - 6\\lambda + 8\\)","solution":"Compute \\(\\det(A - \\lambda I) = \\det\\begin{pmatrix}4-\\lambda&1\\\\0&2-\\lambda\\end{pmatrix} = (4-\\lambda)(2-\\lambda)\\)."},{"type":"regular","q":"What are the eigenvalues of \\(\\begin{pmatrix}0&1\\\\1&0\\end{pmatrix}\\)?","answer":"\\(1\\) and \\(-1\\)","solution":"Solve \\(\\det\\begin{pmatrix}-\\lambda&1\\\\1&-\\lambda\\end{pmatrix} = \\lambda^2 - 1 = 0\\)."},{"type":"regular","q":"Is \\(\\lambda = 0\\) an eigenvalue of \\(\\begin{pmatrix}3&0\\\\0&5\\end{pmatrix}\\)?","answer":"No","solution":"The eigenvalues are 3 and 5 (diagonal entries), so 0 is not an eigenvalue."},{"type":"regular","q":"Find eigenvalues of \\(\\begin{pmatrix}1&2\\\\2&1\\end{pmatrix}\\).","answer":"\\(3\\) and \\(-1\\)","solution":"Solve \\(\\det\\begin{pmatrix}1-\\lambda&2\\\\2&1-\\lambda\\end{pmatrix} = (1-\\lambda)^2 - 4 = \\lambda^2 - 2\\lambda - 3 = 0\\)."},{"type":"regular","q":"The trace of a matrix equals the sum of its ___?","answer":"eigenvalues","solution":"By Vieta's formulas applied to the characteristic polynomial, the coefficient of \\(\\lambda^{n-1}\\) gives the sum of eigenvalues, which equals the trace."},{"type":"regular","q":"What is \\(\\det(A)\\) in terms of eigenvalues \\(\\lambda_1, \\lambda_2, \\ldots, \\lambda_n\\)?","answer":"\\(\\lambda_1 \\lambda_2 \\cdots \\lambda_n\\)","solution":"The determinant is the product of all eigenvalues by Vieta's formulas."},{"type":"regular","q":"For \\(A = \\begin{pmatrix}2&0\\\\0&2\\end{pmatrix}\\), what is the characteristic equation?","answer":"\\((2-\\lambda)^2 = 0\\) or \\(\\lambda^2 - 4\\lambda + 4 = 0\\)","solution":"Compute \\(\\det(A - \\lambda I) = (2-\\lambda)^2\\)."},{"type":"regular","q":"Find the eigenvalues of \\(\\begin{pmatrix}5&-1\\\\-1&5\\end{pmatrix}\\).","answer":"\\(6\\) and \\(4\\)","solution":"Solve \\(\\det\\begin{pmatrix}5-\\lambda&-1\\\\-1&5-\\lambda\\end{pmatrix} = (5-\\lambda)^2 - 1 = \\lambda^2 - 10\\lambda + 24 = 0\\)."},{"type":"word","q":"A vibrating system has a stiffness matrix with eigenvalues 4, 9, and 16. What is the sum of the natural frequencies (eigenvalues)?","answer":"\\(29\\)","solution":"The sum of eigenvalues equals the trace of the matrix, which is \\(4 + 9 + 16 = 29\\)."},{"type":"word","q":"A population model has transition matrix with eigenvalues 0.8, 1.2, and 0.5. Is the population stable in the long term?","answer":"No","solution":"The largest eigenvalue is 1.2 > 1, so the population grows without bound."},{"type":"word","q":"An engineer finds that a system has characteristic polynomial \\(\\lambda^3 - 6\\lambda^2 + 11\\lambda - 6 = 0\\). What is the trace of the matrix?","answer":"\\(6\\)","solution":"The trace equals the sum of eigenvalues, which is the coefficient of \\(\\lambda^2\\) with opposite sign: \\(-(-6) = 6\\)."},{"type":"word","q":"A 3×3 matrix has determinant 24 and eigenvalues 2 and 3. What is the third eigenvalue?","answer":"\\(4\\)","solution":"The product of eigenvalues equals the determinant: \\(2 \\times 3 \\times \\lambda_3 = 24\\), so \\(\\lambda_3 = 4\\)."},{"type":"word","q":"A chemical reaction network has a rate matrix with trace 10 and eigenvalues 2, 3, and 5. Is this consistent?","answer":"Yes","solution":"The sum of eigenvalues \\(2 + 3 + 5 = 10\\) equals the trace."},{"type":"word","q":"In a mechanical system, the stiffness matrix is upper triangular with diagonal entries 7, 9, and 11. What are its eigenvalues?","answer":"\\(7, 9, 11\\)","solution":"For a triangular matrix, the eigenvalues are the diagonal entries."},{"type":"word","q":"A data covariance matrix has trace 50 and determinant 120. If two eigenvalues are 10 and 12, find the third.","answer":"\\(28\\)","solution":"Sum of eigenvalues = trace: \\(10 + 12 + \\lambda_3 = 50\\), so \\(\\lambda_3 = 28\\)."}]);
  add("linearalg", "la5", 1, [{"type":"regular","q":"Find an eigenvector of \\(\\begin{pmatrix}3&0\\\\0&5\\end{pmatrix}\\) for \\(\\lambda = 3\\).","answer":"\\(\\begin{pmatrix}1\\\\0\\end{pmatrix}\\) (or any nonzero scalar multiple)","solution":"Solve \\((A - 3I)v = 0\\): \\(\\begin{pmatrix}0&0\\\\0&2\\end{pmatrix}v = 0\\) gives \\(v = \\begin{pmatrix}1\\\\0\\end{pmatrix}\\)."},{"type":"regular","q":"Is \\(\\begin{pmatrix}1\\\\1\\end{pmatrix}\\) an eigenvector of \\(\\begin{pmatrix}2&1\\\\1&2\\end{pmatrix}\\)?","answer":"Yes, for \\(\\lambda = 3\\)","solution":"Compute \\(A\\begin{pmatrix}1\\\\1\\end{pmatrix} = \\begin{pmatrix}3\\\\3\\end{pmatrix} = 3\\begin{pmatrix}1\\\\1\\end{pmatrix}\\)."},{"type":"regular","q":"Find the eigenspace for \\(\\lambda = 2\\) of \\(\\begin{pmatrix}2&0\\\\0&5\\end{pmatrix}\\).","answer":"\\(\\text{span}\\left\\{\\begin{pmatrix}1\\\\0\\end{pmatrix}\\right\\}\\) or all vectors of the form \\(\\begin{pmatrix}t\\\\0\\end{pmatrix}\\), \\(t \\neq 0\\)","solution":"The eigenspace is the null space of \\(A - 2I = \\begin{pmatrix}0&0\\\\0&3\\end{pmatrix}\\)."},{"type":"regular","q":"What is the dimension of the eigenspace for \\(\\lambda = 1\\) of \\(\\begin{pmatrix}1&1\\\\0&1\\end{pmatrix}\\)?","answer":"\\(1\\)","solution":"Solve \\((A - I)v = 0\\): \\(\\begin{pmatrix}0&1\\\\0&0\\end{pmatrix}v = 0\\) gives a 1-dimensional solution space."},{"type":"regular","q":"Find an eigenvector of \\(\\begin{pmatrix}4&1\\\\0&3\\end{pmatrix}\\) for \\(\\lambda = 4\\).","answer":"\\(\\begin{pmatrix}1\\\\0\\end{pmatrix}\\)","solution":"Solve \\((A - 4I)v = 0\\): \\(\\begin{pmatrix}0&1\\\\0&-1\\end{pmatrix}v = 0\\) gives \\(v = \\begin{pmatrix}1\\\\0\\end{pmatrix}\\)."},{"type":"regular","q":"Is \\(\\begin{pmatrix}0\\\\0\\end{pmatrix}\\) an eigenvector of any matrix?","answer":"No","solution":"The zero vector is excluded from the definition of eigenvectors."},{"type":"regular","q":"Find an eigenvector of \\(\\begin{pmatrix}0&1\\\\1&0\\end{pmatrix}\\) for \\(\\lambda = 1\\).","answer":"\\(\\begin{pmatrix}1\\\\1\\end{pmatrix}\\)","solution":"Solve \\((A - I)v = 0\\): \\(\\begin{pmatrix}-1&1\\\\1&-1\\end{pmatrix}v = 0\\) gives \\(v = \\begin{pmatrix}1\\\\1\\end{pmatrix}\\)."},{"type":"regular","q":"If \\(v\\) is an eigenvector for \\(\\lambda\\), is \\(2v\\) also an eigenvector for \\(\\lambda\\)?","answer":"Yes","solution":"If \\(Av = \\lambda v\\), then \\(A(2v) = 2Av = 2\\lambda v = \\lambda(2v)\\)."},{"type":"word","q":"A structural engineer finds that \\(\\begin{pmatrix}1\\\\2\\end{pmatrix}\\) is an eigenvector of a stiffness matrix for eigenvalue 5. Is \\(\\begin{pmatrix}2\\\\4\\end{pmatrix}\\) also an eigenvector for the same eigenvalue?","answer":"Yes","solution":"Scalar multiples of eigenvectors are eigenvectors for the same eigenvalue."},{"type":"word","q":"In a population model, \\(\\begin{pmatrix}0.9\\\\0.1\\end{pmatrix}\\) is an eigenvector for eigenvalue 1. What does this eigenvector represent?","answer":"A stable age distribution (steady state)","solution":"An eigenvector for eigenvalue 1 represents a distribution that does not change under the transition."},{"type":"word","q":"A network has adjacency matrix \\(A\\) with eigenvector \\(\\begin{pmatrix}1\\\\1\\\\1\\end{pmatrix}\\) for \\(\\lambda = 2\\). What is \\(A\\begin{pmatrix}2\\\\2\\\\2\\end{pmatrix}\\)?","answer":"\\(\\begin{pmatrix}4\\\\4\\\\4\\end{pmatrix}\\)","solution":"Since \\(\\begin{pmatrix}2\\\\2\\\\2\\end{pmatrix} = 2\\begin{pmatrix}1\\\\1\\\\1\\end{pmatrix}\\), we have \\(A\\begin{pmatrix}2\\\\2\\\\2\\end{pmatrix} = 2 \\cdot 2 \\begin{pmatrix}1\\\\1\\\\1\\end{pmatrix} = \\begin{pmatrix}4\\\\4\\\\4\\end{pmatrix}\\)."},{"type":"word","q":"A vibration mode of a building is represented by eigenvector \\(\\begin{pmatrix}1\\\\2\\\\3\\end{pmatrix}\\) with eigenvalue 0.95. Describe the physical meaning.","answer":"The building oscillates in this pattern with amplitude decaying at rate 0.95 per cycle","solution":"The eigenvector defines the shape of oscillation, and eigenvalue < 1 indicates damping."},{"type":"word","q":"For matrix \\(\\begin{pmatrix}5&0\\\\0&5\\end{pmatrix}\\), how many linearly independent eigenvectors are there for \\(\\lambda = 5\\)?","answer":"\\(2\\)","solution":"The eigenspace for \\(\\lambda = 5\\) is \\(\\mathbb{R}^2\\) (null space of zero matrix), which has dimension 2."},{"type":"word","q":"A chemical reaction has eigenvector \\(\\begin{pmatrix}1\\\\2\\\\1\\end{pmatrix}\\) for \\(\\lambda = 0.5\\). If the initial state is \\(\\begin{pmatrix}3\\\\6\\\\3\\end{pmatrix}\\), describe the long-term behavior.","answer":"The state decays exponentially to zero","solution":"Since \\(\\lambda = 0.5 < 1\\) and the initial state is a scalar multiple of the eigenvector, it decays."},{"type":"word","q":"In a Markov chain, the stationary distribution is an eigenvector for which eigenvalue?","answer":"\\(\\lambda = 1\\)","solution":"A stationary distribution satisfies \\(P\\pi = \\pi\\), making it an eigenvector for eigenvalue 1."}]);
  add("linearalg", "la5", 2, [{"type":"regular","q":"If \\(A = PDP^{-1}\\) where \\(D = \\begin{pmatrix}2&0\\\\0&3\\end{pmatrix}\\), what is \\(A^2\\)?","answer":"\\(P\\begin{pmatrix}4&0\\\\0&9\\end{pmatrix}P^{-1}\\)","solution":"\\(A^2 = (PDP^{-1})^2 = PD^2P^{-1} = P\\begin{pmatrix}4&0\\\\0&9\\end{pmatrix}P^{-1}\\)."},{"type":"regular","q":"Can \\(\\begin{pmatrix}1&1\\\\0&1\\end{pmatrix}\\) be diagonalized?","answer":"No","solution":"This matrix has only one linearly independent eigenvector (for \\(\\lambda = 1\\)), so it lacks 2 independent eigenvectors."},{"type":"regular","q":"If a 3×3 matrix has 3 distinct eigenvalues, is it diagonalizable?","answer":"Yes","solution":"Eigenvectors for distinct eigenvalues are linearly independent, so 3 distinct eigenvalues guarantee 3 independent eigenvectors."},{"type":"regular","q":"What does the matrix \\(P\\) contain in the diagonalization \\(A = PDP^{-1}\\)?","answer":"Eigenvectors of \\(A\\) as columns","solution":"Each column of \\(P\\) is an eigenvector corresponding to the eigenvalue in the same position on the diagonal of \\(D\\)."},{"type":"regular","q":"If \\(A = PDP^{-1}\\) with \\(D = \\begin{pmatrix}5&0\\\\0&2\\end{pmatrix}\\), find \\(A^{10}\\).","answer":"\\(P\\begin{pmatrix}5^{10}&0\\\\0&2^{10}\\end{pmatrix}P^{-1}\\)","solution":"\\(A^{10} = PD^{10}P^{-1}\\) where \\(D^{10}\\) has \\(5^{10}\\) and \\(2^{10}\\) on the diagonal."},{"type":"regular","q":"For a symmetric matrix with distinct eigenvalues, are the eigenvectors orthogonal?","answer":"Yes","solution":"Eigenvectors of a symmetric matrix corresponding to distinct eigenvalues are orthogonal."},{"type":"regular","q":"If \\(A\\) is diagonalizable with eigenvalues 2, 2, and 5, how many linearly independent eigenvectors does \\(A\\) have?","answer":"At least 2, at most 3","solution":"The eigenvalue 2 has algebraic multiplicity 2, so geometric multiplicity is between 1 and 2; eigenvalue 5 contributes 1 eigenvector."},{"type":"regular","q":"Is every diagonal matrix diagonalizable?","answer":"Yes","solution":"A diagonal matrix is already in the form \\(D = I \\cdot D \\cdot I^{-1}\\)."},{"type":"word","q":"A population model is represented by \\(A = PDP^{-1}\\) where \\(D = \\text{diag}(0.8, 1.1)\\). Predict the long-term behavior.","answer":"The first mode decays, the second mode grows","solution":"The eigenvalue 0.8 < 1 causes exponential decay in that mode; 1.1 > 1 causes growth."},{"type":"word","q":"An engineer needs to compute \\(A^{50}\\) for a large matrix \\(A\\). Why is diagonalization useful?","answer":"Computing \\(PD^{50}P^{-1}\\) is much faster than multiplying \\(A\\) fifty times","solution":"Raising a diagonal matrix to a power is trivial (raise each diagonal entry), while matrix multiplication is expensive."},{"type":"word","q":"A mechanical system with mass matrix \\(M\\) and stiffness matrix \\(K\\) has a generalized eigenvalue problem. If \\(M\\) is invertible and \\(M^{-1}K = PDP^{-1}\\), what do the eigenvalues of \\(D\\) represent?","answer":"Squared natural frequencies of the system","solution":"In the generalized eigenvalue problem \\(Kv = \\lambda Mv\\), the eigenvalues relate to the system's natural frequencies."},{"type":"word","q":"A 4×4 matrix has eigenvalues 1, 2, 2, 3. Can it be diagonalized with certainty?","answer":"Not necessarily; depends on the geometric multiplicity of eigenvalue 2","solution":"If eigenvalue 2 has geometric multiplicity 2, the matrix is diagonalizable; otherwise it is not."},{"type":"word","q":"In quantum mechanics, an observable is represented by a Hermitian (symmetric complex) matrix. Is it always diagonalizable?","answer":"Yes","solution":"Hermitian matrices are always diagonalizable (spectral theorem)."},{"type":"word","q":"A data compression algorithm uses \\(A = PDP^{-1}\\) to approximate \\(A \\approx P\\tilde{D}P^{-1}\\) where \\(\\tilde{D}\\) keeps only the largest eigenvalues. Why does this work?","answer":"Large eigenvalues capture the most important variance in the data","solution":"Eigenvectors for large eigenvalues represent the dominant patterns; smaller eigenvalues contribute less to the overall structure."},{"type":"word","q":"A Markov chain transition matrix \\(P\\) has eigenvalue 1 with eigenvector \\(\\pi\\) (stationary distribution). If \\(P = QDQ^{-1}\\), what is \\(\\lim_{n \\to \\infty} P^n\\)?","answer":"A matrix with all columns equal to \\(\\pi\\)","solution":"As \\(n \\to \\infty\\), all eigenvalues except 1 vanish (having magnitude < 1), leaving only the eigenvalue-1 component."}]);
  addCum("linearalg", "la5", [{"type":"regular","q":"State the eigenvalue equation.","answer":"\\(Av = \\lambda v\\)","solution":"This is the fundamental definition of an eigenvalue and eigenvector."},{"type":"regular","q":"Write the characteristic equation for finding eigenvalues.","answer":"\\(\\det(A - \\lambda I) = 0\\)","solution":"Eigenvalues are roots of the characteristic polynomial."},{"type":"regular","q":"Find the eigenvalues of \\(\\begin{pmatrix}6&0\\\\0&4\\end{pmatrix}\\).","answer":"\\(6\\) and \\(4\\)","solution":"For a diagonal matrix, eigenvalues are the diagonal entries."},{"type":"regular","q":"What is the relationship between the trace of \\(A\\) and its eigenvalues?","answer":"Trace equals the sum of eigenvalues","solution":"By Vieta's formulas applied to the characteristic polynomial."},{"type":"regular","q":"What is the relationship between \\(\\det(A)\\) and the eigenvalues?","answer":"\\(\\det(A)\\) equals the product of eigenvalues","solution":"The constant term of the characteristic polynomial is \\((-1)^n \\det(A)\\), which equals the product of roots."},{"type":"regular","q":"Find an eigenvector of \\(\\begin{pmatrix}2&1\\\\1&2\\end{pmatrix}\\) for \\(\\lambda = 3\\).","answer":"\\(\\begin{pmatrix}1\\\\1\\end{pmatrix}\\)","solution":"Solve \\((A - 3I)v = 0\\): \\(\\begin{pmatrix}-1&1\\\\1&-1\\end{pmatrix}v = 0\\) gives \\(v = \\begin{pmatrix}1\\\\1\\end{pmatrix}\\)."},{"type":"regular","q":"What is the eigenspace of a matrix for eigenvalue \\(\\lambda\\)?","answer":"The null space of \\(A - \\lambda I\\)","solution":"The eigenspace consists of all solutions to \\((A - \\lambda I)v = 0\\)."},{"type":"regular","q":"If \\(A = PDP^{-1}\\), what does \\(D\\) contain?","answer":"Eigenvalues on the diagonal","solution":"In diagonalization, the diagonal matrix \\(D\\) has eigenvalues as its diagonal entries."},{"type":"regular","q":"What does \\(P\\) contain in the diagonalization \\(A = PDP^{-1}\\)?","answer":"Eigenvectors as columns","solution":"Each column of \\(P\\) is an eigenvector corresponding to the eigenvalue in the same column position of \\(D\\)."},{"type":"regular","q":"How many linearly independent eigenvectors are needed to diagonalize an \\(n \\times n\\) matrix?","answer":"\\(n\\)","solution":"A matrix is diagonalizable if and only if it has \\(n\\) linearly independent eigenvectors."},{"type":"regular","q":"Compute \\(A^3\\) if \\(A = PDP^{-1}\\) with \\(D = \\text{diag}(2, 3)\\).","answer":"\\(P\\text{diag}(8, 27)P^{-1}\\)","solution":"\\(A^3 = PD^3P^{-1}\\) where \\(D^3 = \\text{diag}(2^3, 3^3) = \\text{diag}(8, 27)\\)."},{"type":"regular","q":"Can a matrix with repeated eigenvalues always be diagonalized?","answer":"No","solution":"A repeated eigenvalue may have geometric multiplicity less than its algebraic multiplicity, preventing diagonalization."},{"type":"word","q":"A vibration analysis shows that a system has eigenvalues 0.5, 1.0, and 1.5. Which mode will dominate the long-term behavior?","answer":"The mode with eigenvalue 1.5","solution":"The eigenvalue with largest magnitude dominates long-term behavior; 1.5 > 1.0 > 0.5."},{"type":"word","q":"A population model uses transition matrix \\(A\\) with eigenvalues 0.9, 0.95, and 1.0. Describe the long-term population dynamics.","answer":"The population stabilizes to the eigenvector for eigenvalue 1.0","solution":"Eigenvalues less than 1 decay; eigenvalue 1 represents the stable steady state."},{"type":"word","q":"A 3×3 matrix has trace 12 and determinant 60. If two eigenvalues are 3 and 4, find the third eigenvalue.","answer":"\\(5\\)","solution":"Sum of eigenvalues = trace: \\(3 + 4 + \\lambda_3 = 12\\) gives \\(\\lambda_3 = 5\\). Check: product = \\(3 \\times 4 \\times 5 = 60\\) ✓."},{"type":"word","q":"An engineer diagonalizes a stiffness matrix as \\(K = PDP^{-1}\\) where \\(D = \\text{diag}(100, 400, 900)\\). What are the natural frequencies?","answer":"\\(10, 20, 30\\) (or \\(\\sqrt{100}, \\sqrt{400}, \\sqrt{900}\\))","solution":"Natural frequencies are the square roots of the eigenvalues (stiffness values)."},{"type":"word","q":"A data covariance matrix is diagonalized as \\(C = PDP^{-1}\\) with \\(D = \\text{diag}(50, 20, 5)\\). What percentage of variance is explained by the first principal component?","answer":"\\(62.5\\%\\) (or \\(50/75\\))","solution":"The first eigenvalue is 50 out of total \\(50 + 20 + 5 = 75\\), so \\(50/75 = 2/3 \\approx 66.7\\%\\)."},{"type":"word","q":"A Markov chain has transition matrix \\(P\\) with eigenvalues 1, 0.8, and 0.6. What is the long-term behavior?","answer":"The system converges to the stationary distribution (eigenvector for eigenvalue 1)","solution":"Eigenvalues less than 1 decay; eigenvalue 1 determines the steady state."},{"type":"word","q":"A symmetric matrix \\(A\\) has eigenvalues 2, 2, and 5. Can you guarantee it is diagonalizable?","answer":"No","solution":"Repeated eigenvalue 2 may have geometric multiplicity less than 2, preventing diagonalization (though symmetric matrices are always diagonalizable by the spectral theorem)."},{"type":"word","q":"In a chemical reaction network, the rate matrix has eigenvalues \\(-0.1, -0.5, -1.0\\). What happens to the chemical concentrations over time?","answer":"All concentrations decay exponentially to zero","solution":"All eigenvalues are negative, so all modes decay; the system reaches equilibrium at zero concentration."},{"type":"word","q":"A mechanical system has mass matrix \\(M\\) and stiffness matrix \\(K\\). The generalized eigenvalue problem \\(Kv = \\lambda Mv\\) yields \\(\\lambda = 9\\). What is the natural frequency?","answer":"\\(3\\) (or \\(\\sqrt{9}\\))","solution":"The natural frequency is the square root of the eigenvalue from the generalized problem."},{"type":"word","q":"A 4×4 matrix \\(A\\) has characteristic polynomial \\(p(\\lambda) = (\\lambda - 2)^2(\\lambda - 3)(\\lambda - 4)\\). Is \\(A\\) necessarily diagonalizable?","answer":"Not necessarily","solution":"The repeated eigenvalue 2 may have geometric multiplicity less than 2, preventing diagonalization."},{"type":"word","q":"An image compression algorithm keeps eigenvectors for the 10 largest eigenvalues of a 100×100 covariance matrix. What is the compression ratio?","answer":"\\(10/100 = 0.1\\) or \\(10\\%\\)","solution":"The compressed representation uses 10 eigenvectors instead of 100 dimensions."},{"type":"word","q":"A network graph has adjacency matrix \\(A\\) with largest eigenvalue 5. What does this tell you about the network structure?","answer":"The network has a dominant connected component with spectral radius 5","solution":"The largest eigenvalue (spectral radius) characterizes the network's connectivity and growth properties."}]);
